const input = $input.first()?.json || {};
const chatId = String(input.chat_id || '');
const obj = {
  status: 'error',
  chat_id: chatId,
  image_url: '',
  image_mime_type: '',
  image_b64_preview: '',
  provider_task_id: '',
  report_for_manager: 'Workflow disabled: Gemini/Vertex/Nano Banana removed on 2026-05-25.',
  raw_summary: { provider: 'disabled', reason: 'nanobana_removed_2026_05_25' },
};
return [{ json: obj }];

const src = $('Generate Via Gemini').first().json || {};
const tg = $input.first().json || {};
const messageId = tg.message_id || tg.result?.message_id || '';
const obj = {
  status: 'ok',
  image_url: messageId ? `telegram://message/${messageId}` : '',
  image_mime_type: src.image_mime_type || 'image/png',
  image_b64_preview: src.image_b64_preview || '',
  provider_task_id: String(messageId || ''),
  report_for_manager: 'Gemini успешно сгенерировал и отправил фото в Telegram через sendPhoto.',
  raw_summary: { provider: 'gemini', uploaded_to_telegram: true, message_id: messageId || null }
};
return [{ json: { ...obj, response: JSON.stringify(obj) } }];

const inJson = $input.first().json || {};
let src = {};
try {
  src = $('Generate Via Gemini').first().json || {};
} catch (_) {
  src = {};
}

const sendError = inJson.error?.message || inJson.message || '';
let report = src.report_for_manager || inJson.report_for_manager || 'Gemini не смог сгенерировать фото. Давай сделаем на другом движке: /engine pollinations';

if (sendError) {
  report = `Gemini/Vertex сгенерировал фото, но не смог отправить его в Telegram (${sendError}). Давай сделаем на другом движке: /engine pollinations`;
}

const obj = {
  status: 'error',
  image_url: '',
  image_mime_type: src.image_mime_type || inJson.image_mime_type || '',
  image_b64_preview: src.image_b64_preview || inJson.image_b64_preview || '',
  provider_task_id: '',
  report_for_manager: report,
  raw_summary: src.raw_summary || inJson.raw_summary || {},
};

return [{ json: { ...obj, response: JSON.stringify(obj) } }];

